use std::sync::{Arc, Mutex};
use std::thread;

// Roles: w1, w2 — both workers take the shared resources in the same order.
// Shared resources: a, b — two mutexes contended for by both workers.

fn worker(id: u32, a: Arc<Mutex<()>>, b: Arc<Mutex<()>>) {
    // R5: both workers take the mutexes in the same order (a, then b),
    // so no wait cycle can form and every interleaving terminates (R7).
    // R6: lock() blocks until the mutex becomes free if the other worker holds it.

    // Take mutex a.
    let _guard_a = a.lock().unwrap();

    // Take mutex b. At this point this worker holds both a and b (R2),
    // while the other worker can hold neither (R4).

    // Simulate work while holding both mutexes.
    println!("worker {} holds a and b", id);

    // R3: release each mutex once the work is finished (by dropping the guards).
    drop(_guard_b);
    drop(_guard_a);

    println!("worker {} finished", id);
}

fn main() {
    // R1: main task starts a group of two workers contending for mutexes a and b.
    let a = Arc::new(Mutex::new(()));
    let b = Arc::new(Mutex::new(()));

    let a1 = Arc::clone(&a);
    let b1 = Arc::clone(&b);
    let a2 = Arc::clone(&a);
    let b2 = Arc::clone(&b);

    // w1
    let h1 = thread::spawn(move || worker(1, a1, b1));
    // w2
    let h2 = thread::spawn(move || worker(2, a2, b2));

    // R8: the group finishes only after both workers have completed.
    h1.join().unwrap();
    h2.join().unwrap();

    // R9: print exactly the required line, then exit.
    println!("DONE done=1");
}
```

**How the requirements are met:**

- **R1**: `main` spawns two threads (`w1`, `w2`) that both contend for the same two mutexes `a` and `b` (shared via `Arc`).
- **R2**: Each worker locks `a` first, then `b`; between the two acquisitions and the drops, it holds both simultaneously.
- **R3**: Each guard is explicitly dropped when the worker's work is done, releasing each mutex exactly once.
- **R4**: Guaranteed by `Mutex` semantics — only one thread can hold a given mutex at a time.
- **R5**: Both workers acquire in the identical order (`a` → `b`), so the resource allocation graph stays acyclic and no deadlock cycle can form.
- **R6**: `lock()` blocks until the mutex is free.
- **R7**: With a consistent lock ordering and blocking (not failing) acquisition, every possible interleaving terminates.
- **R8**: `main` joins both worker handles before proceeding.
- **R9**: The program prints exactly `DONE done=1` and exits.

```rust
use std::sync::{Arc, Condvar, Mutex};
use std::thread;

fn main() {
    // R2: one lock (m), one condition variable (cv), one boolean flag (ready) guarded by the lock.
    let shared = Arc::new((Mutex::new(false), Condvar::new()));
    let (m, cv) = (&shared.0, &shared.1);

    // Waiter role
    let waiter_shared = Arc::clone(&shared);
    let waiter = thread::spawn(move || {
        let (m, cv) = (&waiter_shared.0, &waiter_shared.1);
        // R4: check the flag while holding the lock; wait only while flag is false;
        // re-check after every wake. R7: lock is released while blocked.
        let mut ready = m.lock().unwrap();
        while !*ready {
            ready = cv.wait(ready).unwrap();
        }
        // R4: waiter completes once the flag is true.
        *ready
    });

    // Notifier role
    let notifier_shared = Arc::clone(&shared);
    let notifier = thread::spawn(move || {
        let (m, cv) = (&notifier_shared.0, &notifier_shared.1);
        // R3: set the flag to true while holding the lock, signal, then release.
        let mut ready = m.lock().unwrap();
        // R6: flag is set to true before the signal is issued.
        *ready = true;
        cv.notify_one();
        drop(ready); // release the lock
    });

    // R1: both roles run at the same time; R8: wait for both to finish.
    let waiter_result = waiter.join().unwrap();
    notifier.join().unwrap();

    // R9: the flag is true in every schedule; R5: waiter completes even if the
    // signal happened before it started waiting (flag check prevents missed wakeups).
    // R10: print exactly the required line and exit.
    println!("DONE ready={}", waiter_result);
}
